import sys
from math import gcd

def min_operations_to_one(n, a):
    if 1 in a:
        return n - a.count(1)

    total_gcd = a[0]
    for num in a[1:]:
        total_gcd = gcd(total_gcd, num)

    if total_gcd != 1:
        return -1

    operations = 0
    for i in range(n):
        if a[i] == 1:
            continue
        for j in range(i + 1, n):
            if a[j] == 1:
                break
            a[j] = gcd(a[j], a[j - 1])
            operations += 1
            if a[j] == 1:
                break

    return operations

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = list(map(int, data[1:]))

    result = min_operations_to_one(n, a)
    print(result)

